import {
  Area,
  AreaChart,
  CartesianGrid,
  ResponsiveContainer,
  Tooltip,
  XAxis,
  YAxis,
} from 'recharts';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Clock } from 'lucide-react';
import ridesByHour from '@/data/rides_by_hour.json';
import type { RidesByHour } from '@/types/charts';
import { axisTick, formatRideTick, tooltipStyle } from './chartTheme';

/**
 * Ride volume by hour of day — train.ipynb cell 6 (`df.hour.value_counts().sort_index()`),
 * generated by scripts/generate_chart_data.py. Answers "busiest time of the day".
 */
export function RidesByHourChart() {
  const data = ridesByHour as RidesByHour[];

  return (
    <Card className="rounded-lg border">
      <CardHeader className="flex-row items-center gap-2 space-y-0 pb-3">
        <Clock className="h-5 w-5 text-muted-foreground" />
        <div>
          <CardTitle className="text-lg font-semibold">Rides by Hour of Day</CardTitle>
          <CardDescription className="text-sm">Busiest time of the day</CardDescription>
        </div>
      </CardHeader>
      <CardContent>
        <ResponsiveContainer width="100%" height={240}>
          <AreaChart data={data} margin={{ top: 10, right: 10, left: 10, bottom: 0 }}>
            <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" vertical={false} />
            <XAxis
              dataKey="hour"
              tick={axisTick}
              axisLine={false}
              tickLine={false}
              tickFormatter={(hour: number) => `${hour}:00`}
            />
            <YAxis
              tick={axisTick}
              axisLine={false}
              tickLine={false}
              tickFormatter={formatRideTick}
            />
            <Tooltip
              cursor={{ stroke: 'var(--border)' }}
              contentStyle={tooltipStyle}
              formatter={(value) => [
                typeof value === 'number' ? value.toLocaleString() : String(value),
                'Rides',
              ]}
              labelFormatter={(label) => `${label}:00`}
            />
            <Area
              type="monotone"
              dataKey="rides"
              stroke="var(--chart-1)"
              strokeWidth={2}
              fill="var(--chart-1)"
              fillOpacity={0.2}
            />
          </AreaChart>
        </ResponsiveContainer>
      </CardContent>
    </Card>
  );
}
